INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','Фосилаи ғаллай дар парҳези гӯб: стандардҳои тавсияшуда барои кишоварон' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Санҷиши стандарди асосӣ барои таъмини ғаллайҳои гӯб барои кишоварони Тоҷикистон. Дар ин мақола ҷавобгӯии тавсияшуда барои фосилаи ғаллай дар парҳези гӯб мебошад. Ин маълумот барои таъмини парҳези беҳтар ва баланд бардохтани истеҳсоли гӯб муҳим аст. Ҳамаи маълумот аз AFP гирифта шудааст ва барои кишоварони Тоҷикистон истифода мешавад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
