INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Чаро кунҷид ба идоракунии дақиқи манбаъҳои об ниёз дорад?</h2>\n<p>Кунҷид (<em>Guizotea oleifera</em>) яке аз қадимтарин маҳсулоти равғаннок дар ҷаҳон мебошад, ки ба сабаби таркиби баланди равған (тақрибан 35 то 50 фоиз дар тоб) ва истифодаи васеъ дар саноати ғизоӣ ва доруӣ дар кишоварӣ ҷойгоҳи хос дорад. Яке аз вазъиятҳои асосӣ дар парҳези кунҷид ҳассосияти ин растани ба зарари реша мебошад. Кунҷид растании аст, ки дар фишкирдани реша ва таҳамили кам ба хушкӣ дар марҳилаҳои аввали рӯяндӣ, ниёз ба истеъмoli дақиқ ва ҳадафноки оро ба соҳаи кор меорад. Бинобар ин, истифодаи технологияҳои нав, чунин <a href="https://navar-abyari.ir/%D8%A2%D9%85%D9%88%D8%B2%D8%B4-%D8%A7%D8%B3%D8%AA%D9%81%D8%A7%D8%AF%D9%87-%D8%A7%D8%B2-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">омӯзиши истифода аз пайпори тиббӣ</a> метавонад самаранокии истафодаи обро ба таври назаррас зиёд кунад ва аз хомӯшидани манбаъҳои қимматиманд пешгирӣ кунад. Дар минтақаҳои хушк ва нисбатан хушк, ҷое ки баронҳо ноҳамвор ва камфойда ҳастанд, такя ба обориши ғарқобӣ на танҳо боиси шорӣшавии хок мегардад, балки решаҳои нозуки кунҷидро дар таҳдиди баланди бемориҳои қалавӣ мегирад. Бинобар ин, гузашт аз усулҳои анъанавӣ ба усулҳои муосир ва ҷавонмаро, як зарурати иқтисодӣ ва экологӣ аст, ки бояд ба назар гирифта шавад, то суднокии боғзорӣ нигоҳ дошта шавад.</p>\n\n<h2>Чаро аз системаи пайпори тиббӣ барои кунҷид истифода барем?</h2>\n<p>Абришазӣи сачмавӣ ва махсусан системаи шитоби нукҳо, бо вуҷуд тақсимоти баробари об ва парҳезкунанда дар решаҳои растаниҳо, вариантбе бештар баръайни абришазӣи анъанавии рӯягӣ мебошад. Дар ин усул, об бо фишори паст ва оқими паст дар наздикии ҷойи партовӣи бобҳо ё нургузорон равшан мешавад. Ин боиси он мегардад, ки намӣ дар минтақаи решаҳо нигоҳ дошта шавад ва аз шустан ва оббурдӣ ва парҳезкунандаи растаниҳо пешгирӣ карда шавад. Баръайни усулҳои кӯҳна, ки дар онҳо об бо озодӣ ба сатҳи замин равшан мешавад, шитоби нукҳо имкон медиҳад, ки об танҳо ба қабатҳои чуқуртари замин расад. Ин хусусият боиси кам будани астронки рӯягӣ мегардад, зеро намии рӯягӣ камтар аст. Инчунин, азбаски сатҳи ҷойҳои хушк боқӣ мемонад, фаъолияти зараррасони зараррасониҳо ва сеъе зараррасониҳо, ки дар намии баланд фаъоланд, кам мешавад.</p>\n<h3>Баровариҳои асосии шитоби нукҳо дар партови кунҷи</h3>\n<ul>\n<li><strong>Броқорӣ дар истифодаи об:</strong> Кам кардани истифодаи об то 30 то 40 фоиз нисбат ба абришазӣи хунӯгӣ.</li>\n<li><strong>Кам кардани бемориҳои қулайӣ:</strong> Хушқ蒙ии баргҳо аз падои қулайӣ пешгирӣ мекунад ва ниёз ба дубора парҳезкунандаро кам мекунад.</li>\n<li><strong>Партови зерандок:</strong> Имкони партовӣ дар масофаҳои камтар аз сабаби истифодаи оптималии масофаи байни рельсҳои абришазӣ.</li>\n<li><strong>Изофҳар кардани суръати рушд:</strong> Дастрасии доимӣ ба намӣ дар решаҳо боиси таъкиди рушди вегетативӣ ва истеҳсоли бобунаки қавитар ва равғанмонанди бардштар мегардад.</li>\n</ul>\n\n<h2>Омода кардани хураки кортӣ ва боркунии бобунак</h2>\n<p>Пеш аз оғоzi кортӣ, тавзеҳи дақиқи физиологияи ҷанс дар шартҳои маҳаллӣ муҳим аст. Бобунак ба хокҳои сабуку нигаронанда бо pH-и мувозинатдӯст дӯст дорад. Беҳтар аст, ки хураки кортиро бо корҳои заминии мувофиқ омода кунед, то тахшҳои хок аз пӯшидашавӣ пешгирӣ шаванд. Омода кардани мувофиқи хурак аз меъёрди чуқур ва тиркишҳои мулоим иборат аст, то сатҳи хок ҳамвор ва бе корда бодад. Ин кор кафолат медиҳад, ки оби нӯгони нӯрокӣ бо шакли равшан дар чукурбории кортӣ ҷазб карда шавад. Агар хоки шумо вазнин бошад, илова кардани моддаҳои органикӣ метавонад сохтори хокро беҳтар намотад ва гузаришкунандагиро зиёд кунад. Илова бар ин, ислоҳи намакии хок пеш аз боркунӣ барои навлди бобунаке, ки ба намак ҳассос аст, муҳим аст.</p>\n<h3>Иваз кундани ҳаҷми бобунак дар як гектар</h3>\n<p>Миқдори бобунаки лозима барои кортӣ дар як гектар вобаста ба намуди навл, вазни ҳазор дона ва усули кортӣ аст. Дар ҳолати умумӣ, барои бобунаки бобунак истифодаи 15 то 20 килограмм бобунак дар як гектар тавсия дода мешавад. Ин миқдorz метавонад вобаста ба шароити иқлим ва сифати бобунак тағйир ёбад. Барои шиносоии бештар бо ҳисобҳои дақиқ, омӯзиш <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%AE%D8%B1%D8%A8%D8%B2%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори бобунаки тухми хурмак дар як гектар</a> Ҳамчун намунаи дигар ҷансҳои ҳассос метавонад назари умумиро оид ба ҳисобҳои кишоварзӣ диҳад. Интихоби бобунаки сифати баланд ва дорои потенсиали хуби таррӣ, калиди муваффақият дар марҳилаи кортӣ аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کنجد-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت کنجد با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кишт, нақшаи обёрории булӯри қатқатии кишт, кунҷид</figcaption></figure>\n\n<p>Балҳои кунҷид одатан тавассути сеялкӯбкунанда ё дастӣ дар наздикии шитоби тиқ борӣ карда мешаванд. чуқурии борӣ одатан 2 то 3 сантиметр аст. Баъд аз борӣ, як обёрории пурраи ибтидоӣ барои фаъолсозии балҳо зарур аст. Ин обёрории ибтидоӣ бояд нарм бошад, то балҳо ҷойивазӣ нашаванд. Фосила байни бал ва шитоби тиқ бояд дақиқан риоя карда шавад, зеро об наметонад мустақиман ба балҳо пурсад ва боиси лағзидани сохторшавӣ гардад.</p>\n\n<h2>вақтандозии обёрории қатқатии кунҷид</h2>\n<p>Идоракунии нақшаи вақти обёрӣ (Irrigation schedule) муҳимтарин қисм дар парвариши кунҷид бо системаи қатқатӣ мебошад. Ин нақша бар асоси марҳилаҳои рушди растани, ниёзи муҳим ба намнокӣ ва шароити иқлим танзим карда мешавад. Пайгирӣи узвӣ хок бо хоскунандаҳо метавонад дақиқии ин вақтандозиро афзониш бахшанд. Азбаски кунҷид дар марҳилаҳои ҳассос, ба монанди гашадгӣ, ба фишори об хеле ҳассос аст, ҳар гуна дарди шадиди намнокӣ метавонад боиси пароканда шудани гулҳо ва кам шудани ҳосил гардад.</p>\n<h3>Ҷадвали нақшаи вақти обёрӣ (Irrigation schedule)</h3>\n<ol>\n<li><strong>Марҳилаи ҷавросозӣ ва заррагӣ:</strong> Дар 7 то 10 рӯзи аввал, ниёз ба обёрории сабуку бисор дастрас аст, то намноки хок нигоҳ дошта шавад. Дар ин марҳила, суръати ҷорӣ бояд паст бошад.</li>\n<li><strong>Рӯшди вегетативӣ (Vegetative stage):</strong> Аз 10 то 30 рӯзӣ, бо зиёдшудани ҳаҷми афзоишӣ, сарфшавии оби системаи ғарғаравӣ (тип) меафзояд. Шумораи оҳиста кардани обҳо то 2 ё 3 маротиба дар ҳафта мерасад. Дар ин давра, наботат пардаи афзоишии худро васеъ мекунад.</li>\n<li><strong>Рӯзгории афзоишӣ (Ғунбӯд кардан) & Fruit Set):</strong> Ин марҳалаи ҳассостарин аст. Обиёб бояд мунтазам ва бе тағйироти шадид бошад, то тобӯри дон ба ҳадди оптималӣ расад. Кӯтоҳии об дар ин марҳала мустақиман вазни пусҳо/донҳоро кам мекунад.</li>\n<li><strong>Пуршудани дон (Seed Filling):</strong> Дар ҳафтаҳои охирин, обиёб бо тадриҷ қатъ карда мешавад, то наботат барои расиши дон омода шавад. Ин ҷоҳазирӣ ба монанди <a href="https://navar-abyari.ir/fawa-id-nawwar-ttip-bghl-dw-kht/">фоидҳои системаи ғарғаравӣ (тип) дар нақли кӯҳӣ</a> аст, ки ба кам шудани хароҷоти амалиётҳо ва зиёд шудани сифати ниҳоӣ таъкид мекунад. Қатъ кардани об бояд тадриҷӣ бошад, то фишори ғоят тез ба наботат ворид нашавад.</li>\n</ol>\n\n<h2>Нуқтаҳои амалӣ ва техникӣ дар истифодаи системаи ғарғаравӣ (тип)</h2>\n<p>Истифодаи дурусти системаи оварӣ ба диққатнокӣ дар насб ва нигоҳдорӣ ниёз дорад. Яке аз нуқтаҳои асосӣ ин интихоби намуди мувофиқи нури дрип (ribs) мебошад. Барои чигирифт (sesame), нури дрип бо сарбанди 1 то 1.5 литр дар соат одатан самараноканд. Интихоби дурусти дрипчакҳо вобаста ба намуди хок низ муҳим аст. Дар хокҳои гилӣ дрипчакҳо бо сарбанди баландтар ва дар хокҳои рӯмолӣ (шеба) дрипчакҳо бо сарбанди пасттар тавсия дода мешаванд.</p>\n<h3>Идоракунии филтр ва фишор</h3>\n<p>Мекони ҳатман бояд аз филтри мувофиқ (шабакавӣ, дискӣ ё уголӣ) истифода баред, то хостани дрипчакҳоро пешгирӣ кунед. Фишори воридшаванда ба нури дрип бояд байни 0.5 то 1 бар танзим карда шавад. Агар фишор камтар бошад, тақсимоти об баробар нест ва агар зиёд бошад, ба нури зарар мерасад. Инчунин, нигоҳдории мунтазами система ва тоза кардани филтрҳо пас аз ҳар як истифода муҳлати фаъолии системаро зиёд мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کنجد-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت کنجد با آبیاری قطره‌ای - تصویر 2"/><figcaption>method of planting crop drip irrigation schedule chigirift</figcaption></figure>\n\n<p>Инчунин, дар охирҳои ҳар фавсол нури дрипро ҳаргиз қаторда некунед, то дар фавсоли оянда истифода шавад ё бо роҳи дуруст ҷамъ карда шавад. Барои шиносӣ бо роҳҳои афзайиши ҳосилот, модори мақолаи... <a href="https://navar-abyari.ir/clover-yield-per-hectare-factors-increase/">clover yield per hectare factors increase</a> Ишора мекунад, ки принсипҳои монанд дар идоракунии кишоварзии люцерн низ ба чигирифт дахл доранд. Идоракунии беҳтарини манбаъҳо ва назорати доимӣ калиди афзайиши самаранокӣ дар ҳар як кӯштист.</p>\n\n<h2>маҷмӯи усулҳои муосири оварӣ</h2>\n<p>Технологияҳои имрӯза дар оварии дрип системҳоро ҳушндор (smart) кардаанд. Истифодаи сенсорҳои намуди хок метавонад вақти овариро дақиқтар аз ҳар як ҷадвали вақти собит муайян кунад. Ин таҳлил як қисми усулҳои муосири оварии замини кишоваршӣ ба ҳисоб меравад, ки ба деҳқонон имкон медиҳад вобаста ба омадҳои лаҳзавӣ қарор диҳанд. Пайваст кардани системаи оварӣ ба Internet of Things (IoT) имкони назорати аз дур ва идоракунии худкори дарҳои обро фароҳам меорад.</p>\n\n<h2>Саволҳои марказӣ (FAQ)</h2>\n<h3>Оё системаи қатқатӣ дар хокҳои вазнин хуб кор мекунад?</h3>\n<p>Бале, аммо дар хокҳои вазнин ҷоришавии об бадтар аст, бинобар ин бояд фосилаи байни линияҳои қатқатиро зиёд кунед ва сари обро баланд бардоред, то шурории намӣ дар решаҳо ҷамъ нашавад. Инчунин беҳтар аст, ки аз заминҳои ҷоришаванда истифода баред, то зиёди об хориҷ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کنجد-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت کنجد با آبیاری قطره‌ای - تصویر 3"/><figcaption>усулҳои парвариш қатқатӣ об оварӣ ҷадвал ҳасис</figcaption></figure>\n\n<h3>Кадом фосила барои парвариши ҳасис дар системаи қатқатӣ мувофиқ аст?</h3>\n<p>Вобаста ба навъ, одатан 45 то 50 сантиметр байни шохумҳо ва 40 то 45 сантиметр байни сатрҳо тавсия дода мешавад. Системаи қатқатӣ метавонад дар қоида ё зери сатҳи хок дар наздикии сатри парвариш ҷойгир бошад. Риъоя кардани ин фосилаҳо барои дастрасии тайёрот ва ҳавогузаронии мувофиқ байни шохумҳо зарур аст.</p>\n<h3>Оё метавон отади ҳалшуда тавассути системаи қатқатӣ ба ҳасис дод?</h3>\n<p>Бале, системаҳои қатқатӣ бо сабаби наздикии ба решаҳо, беҳтарин усул барои отади моеъ мебошанд. Ин кор ба ҷабзиши тезтари моддаҳои ғизоӣ ва кам кардани парешии отад оварда мерасонад. Отади нуқтавӣ (Fertigation) самаранозукии баландтарро дар муқоиса бо парши сатҳӣ дорад.</p>\n\n<h2>Хулоса</h2>\n<p>Кашт намҳои чанг бо озири қатраҳо ва натиб як усули устувор, анъомӣ ва иқтиёснок аст, ки дар шароити камобии оби имрӯз ҳатмӣ шудааст. Бо риояи асосҳои барраси андозагири, интихоби хаммои мувофиқ ва идоракунии дурусти системаи озири, метавон ба ҳосилнокӣ ва сифати баланди хами чанги равғандор умедвояманд буд. татбиқ <a href="https://navar-abyari.ir/zira-sabz-tukhm-miqdor-gaektar-kisht-parastori/">Зароси сабук, татбиқ кардани миқдори гектарӣ, кшт ва пулдоркунӣ</a> метавонад ба монанди роҳнамоии амалии кшҳои дигар ба кор барояд. Ошоматӣ ба ҷузъиёти техникӣ ва киштӣ на танҳо фоидаи иқтисодии деҳқонро таъмин мекунад, балки дар нигоҳубини муҳити зист ва манбаъҳои об барои наслҳои оянда кӯмаки муҳим мебахшад. Саҳмгузорӣ дар асосҳо озири муосира як қадам ба самти кишоварзии дақиқ ва оянданокист.</p>','Комиллӣи ҷинсиии ғурури ғурури бо об андозаи ғурури','Дар ин мақолаи пурра, ҳамаи ҷиҳатҳои киштии кунҷубо бо истифода аз системаҳои обдиҳии биндакӣ ва навбандии типӣ баррасӣ карда мешавад; аз тайёркунии тоҳук то расидан ба вақти муайяни обдиҳӣ ва идоракунии таркиши замин.','publish','closed','closed','komsilli-ghurur-ghurur-ob-andozavi-ghurur',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
